<?php
namespace App\Application\Claims;
use App\Application\Audit\AuditWriter;use App\Application\Events\OutboxWriter;use App\Domain\Claims\ClaimLifecycle;use App\Models\{Claim,ClaimDecision,ClaimDispute,ClaimRecovery,ClaimReserveChange,Policy,User};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
final class ClaimLifecycleService{
public function __construct(private ClaimLifecycle$machine,private ClaimCommandGuard$guard,private AuditWriter$audit,private OutboxWriter$outbox){}
public function fnol(string$tenant,array$d,User$actor):Claim{$replay=$this->guard->replay($tenant,'FNOL',$d['idempotency_key'],$d);if($replay)return Claim::findOrFail($replay['id']);return DB::transaction(function()use($tenant,$d,$actor){$p=Policy::where(['id'=>$d['policy_id'],'tenant_id'=>$tenant])->lockForUpdate()->first();if(!$p||!in_array($p->status,['ACTIVE','EXPIRING','ENDORSEMENT_PENDING'],true))throw ValidationException::withMessages(['policy_id'=>__('wave7.policy_invalid')]);if($p->party_id!==$d['claimant_party_id'])throw ValidationException::withMessages(['claimant_party_id'=>__('wave7.claimant_invalid')]);$loss=\Carbon\CarbonImmutable::parse($d['loss_occurred_at']);if($loss->lt($p->coverage_starts_at)||$loss->gt($p->coverage_ends_at))throw ValidationException::withMessages(['loss_occurred_at'=>__('wave7.loss_outside_cover')]);$c=Claim::create(['tenant_id'=>$tenant,'policy_id'=>$p->id,'claimant_party_id'=>$d['claimant_party_id'],'claim_number'=>'CLM-'.now()->format('Ym').'-'.strtoupper(Str::random(10)),'status'=>'SUBMITTED','loss_occurred_at'=>$d['loss_occurred_at'],'loss_details'=>$d['loss_details'],'loss_location'=>$d['loss_location']??null,'estimated_loss_minor'=>$d['estimated_loss_minor']??null,'currency'=>$p->currency,'priority'=>$d['priority']??'NORMAL','submitted_at'=>now()]);$this->event($c,'DRAFT','SUBMITTED','FNOL_SUBMITTED','FNOL',$actor,[]);$response=['id'=>$c->id,'claim_number'=>$c->claim_number,'status'=>$c->status];$this->guard->store($tenant,'FNOL',$d['idempotency_key'],$c->id,$d,$response);$this->audit->record('claim.fnol.submitted','claim',$c->id,$response);$this->outbox->record('claim.fnol.submitted','claim',$c->id,$response);return$c;});}
public function assign(Claim$c,User$assignee,string$reason,User$actor):Claim{return DB::transaction(function()use($c,$assignee,$reason,$actor){$c=Claim::whereKey($c->id)->lockForUpdate()->firstOrFail();$this->tenant($c);if($c->assigned_to)DB::table('claim_assignments')->where(['claim_id'=>$c->id,'assignee_id'=>$c->assigned_to])->whereNull('released_at')->update(['released_at'=>now()]);DB::table('claim_assignments')->insert(['id'=>(string)Str::uuid(),'claim_id'=>$c->id,'assignee_id'=>$assignee->id,'assigned_by'=>$actor->id,'reason_code'=>$reason,'assigned_at'=>now()]);$c->update(['assigned_to'=>$assignee->id,'version'=>$c->version+1]);$this->audit->record('claim.assigned','claim',$c->id,['assignee_id'=>$assignee->id],$reason);$this->outbox->record('claim.assigned','claim',$c->id,['assignee_id'=>$assignee->id]);return$c->refresh();});}
public function transition(Claim$c,string$to,string$reason,array$details,User$actor):Claim{return DB::transaction(function()use($c,$to,$reason,$details,$actor){$c=Claim::whereKey($c->id)->lockForUpdate()->firstOrFail();$this->tenant($c);$this->machine->assert($c->status,$to);$from=$c->status;$u=['status'=>$to,'version'=>$c->version+1];if($to==='ACKNOWLEDGED')$u['acknowledged_at']=now();if($to==='CLOSED'){$u['closed_at']=now();$u['closure_summary']=$details['closure_summary']??null;}if($to==='REOPENED'){$u['closed_at']=null;$u['reopened_at']=now();$u['reopened_by']=$actor->id;}$c->update($u);$this->event($c,$from,$to,'STATUS_CHANGED',$reason,$actor,$details);$this->audit->record('claim.transitioned','claim',$c->id,['from'=>$from,'to'=>$to],$reason);$this->outbox->record('claim.transitioned','claim',$c->id,['from'=>$from,'to'=>$to]);return$c->refresh();});}
public function requestReserve(Claim$c,int$amount,string$reason,?string$notes,User$actor):ClaimReserveChange{if($amount<0)throw ValidationException::withMessages(['amount_minor'=>__('wave7.amount_invalid')]);return DB::transaction(function()use($c,$amount,$reason,$notes,$actor){$c=Claim::whereKey($c->id)->lockForUpdate()->firstOrFail();$this->tenant($c);if(ClaimReserveChange::where(['claim_id'=>$c->id,'status'=>'PENDING_APPROVAL'])->exists())throw ValidationException::withMessages(['status'=>__('wave7.reserve_pending')]);return ClaimReserveChange::create(['claim_id'=>$c->id,'previous_amount_minor'=>$c->current_reserve_minor,'requested_amount_minor'=>$amount,'currency'=>$c->currency,'status'=>'PENDING_APPROVAL','reason_code'=>$reason,'notes'=>$notes,'requested_by'=>$actor->id]);});}
public function approveReserve(ClaimReserveChange$r,User$actor):ClaimReserveChange{return DB::transaction(function()use($r,$actor){$r=ClaimReserveChange::whereKey($r->id)->lockForUpdate()->firstOrFail();$c=Claim::whereKey($r->claim_id)->lockForUpdate()->firstOrFail();$this->tenant($c);if($r->status!=='PENDING_APPROVAL'||$r->requested_by===$actor->id)throw ValidationException::withMessages(['status'=>__('wave7.approval_invalid')]);$r->update(['status'=>'APPROVED','approved_by'=>$actor->id,'approved_at'=>now()]);$c->update(['current_reserve_minor'=>$r->requested_amount_minor,'version'=>$c->version+1]);$this->audit->record('claim.reserve.approved','claim_reserve_change',$r->id,['amount_minor'=>$r->requested_amount_minor]);$this->outbox->record('claim.reserve.approved','claim',$c->id,['reserve_change_id'=>$r->id]);return$r->refresh();});}
public function proposeDecision(Claim$c,array$d,User$actor):ClaimDecision{return DB::transaction(function()use($c,$d,$actor){$c=Claim::whereKey($c->id)->lockForUpdate()->firstOrFail();$this->tenant($c);if($c->status!=='CARRIER_REVIEW')throw ValidationException::withMessages(['status'=>__('wave7.decision_stage_invalid')]);if(ClaimDecision::where(['claim_id'=>$c->id,'status'=>'PENDING_APPROVAL'])->exists())throw ValidationException::withMessages(['status'=>__('wave7.decision_pending')]);$snapshot=$this->authority($c,(int)$d['approved_amount_minor'],$actor);return ClaimDecision::create(['claim_id'=>$c->id,'decision'=>$d['decision'],'approved_amount_minor'=>$d['approved_amount_minor'],'currency'=>$c->currency,'reason_code'=>$d['reason_code'],'rationale'=>$d['rationale'],'authority_snapshot'=>$snapshot,'status'=>'PENDING_APPROVAL','proposed_by'=>$actor->id]);});}
public function approveDecision(ClaimDecision$d,User$actor):Claim{return DB::transaction(function()use($d,$actor){$d=ClaimDecision::whereKey($d->id)->lockForUpdate()->firstOrFail();$c=Claim::whereKey($d->claim_id)->lockForUpdate()->firstOrFail();$this->tenant($c);if($d->status!=='PENDING_APPROVAL'||$d->proposed_by===$actor->id)throw ValidationException::withMessages(['status'=>__('wave7.approval_invalid')]);$this->authority($c,$d->approved_amount_minor,$actor);$to=match($d->decision){'APPROVE'=>'APPROVED','PARTIAL'=>'PARTIALLY_APPROVED','DECLINE'=>'DECLINED',default=>throw ValidationException::withMessages(['decision'=>__('wave7.decision_invalid')])};$this->machine->assert($c->status,$to);$d->update(['status'=>'APPROVED','approved_by'=>$actor->id,'approved_at'=>now()]);$from=$c->status;$c->update(['status'=>$to,'approved_amount_minor'=>$d->approved_amount_minor,'version'=>$c->version+1]);$this->event($c,$from,$to,'DECISION_APPROVED',$d->reason_code,$actor,['decision_id'=>$d->id]);$this->audit->record('claim.decision.approved','claim_decision',$d->id,['claim_id'=>$c->id,'amount_minor'=>$d->approved_amount_minor]);$this->outbox->record('claim.decision.approved','claim',$c->id,['decision_id'=>$d->id]);return$c->refresh();});}
public function openDispute(Claim$c,array$d,User$actor):ClaimDispute{return DB::transaction(function()use($c,$d,$actor){$c=Claim::whereKey($c->id)->lockForUpdate()->firstOrFail();$this->tenant($c);if(!in_array($c->status,['DECLINED','PARTIALLY_APPROVED'],true)||ClaimDispute::where(['claim_id'=>$c->id,'status'=>'OPEN'])->exists())throw ValidationException::withMessages(['status'=>__('wave7.dispute_invalid')]);$x=ClaimDispute::create(['claim_id'=>$c->id,'reference'=>'DSP-'.strtoupper(Str::random(12)),'status'=>'OPEN','reason_code'=>$d['reason_code'],'statement'=>$d['statement'],'opened_by'=>$actor->id]);$from=$c->status;$c->update(['status'=>'DISPUTED','version'=>$c->version+1]);$this->event($c,$from,'DISPUTED','DISPUTE_OPENED',$d['reason_code'],$actor,['dispute_id'=>$x->id]);return$x;});}
public function resolveDispute(ClaimDispute$d,string$resolution,bool$reassess,User$actor):ClaimDispute{return DB::transaction(function()use($d,$resolution,$reassess,$actor){$d=ClaimDispute::whereKey($d->id)->lockForUpdate()->firstOrFail();$c=Claim::whereKey($d->claim_id)->lockForUpdate()->firstOrFail();$this->tenant($c);if($d->status!=='OPEN')throw ValidationException::withMessages(['status'=>__('wave7.dispute_invalid')]);$d->update(['status'=>'RESOLVED','resolution'=>$resolution,'resolved_by'=>$actor->id,'resolved_at'=>now()]);if($reassess){$this->machine->assert($c->status,'CARRIER_REVIEW');$c->update(['status'=>'CARRIER_REVIEW','version'=>$c->version+1]);}$this->audit->record('claim.dispute.resolved','claim_dispute',$d->id,['reassess'=>$reassess]);$this->outbox->record('claim.dispute.resolved','claim',$c->id,['dispute_id'=>$d->id]);return$d->refresh();});}
public function recovery(Claim$c,array$d,User$actor):ClaimRecovery{$this->tenant($c);return ClaimRecovery::create(['claim_id'=>$c->id,'type'=>$d['type'],'status'=>'OPEN','counterparty_name'=>$d['counterparty_name'],'target_amount_minor'=>$d['target_amount_minor'],'currency'=>$c->currency,'reference'=>'RCV-'.strtoupper(Str::random(12)),'notes'=>$d['notes']??null,'opened_by'=>$actor->id]);}
public function recordRecovery(ClaimRecovery$r,int$amount,bool$close,User$actor):ClaimRecovery{return DB::transaction(function()use($r,$amount,$close,$actor){$r=ClaimRecovery::whereKey($r->id)->lockForUpdate()->firstOrFail();$this->tenant($r->claim);$total=$r->recovered_amount_minor+$amount;if($amount<=0||$total>$r->target_amount_minor||$r->status!=='OPEN')throw ValidationException::withMessages(['amount_minor'=>__('wave7.recovery_invalid')]);$r->update(['recovered_amount_minor'=>$total,'status'=>$close||$total===$r->target_amount_minor?'CLOSED':'OPEN','closed_at'=>$close||$total===$r->target_amount_minor?now():null]);$this->audit->record('claim.recovery.recorded','claim_recovery',$r->id,['amount_minor'=>$amount,'actor_id'=>$actor->id]);return$r->refresh();});}
private function authority(Claim$c,int$amount,User$actor):array{$roles=$actor->memberships()->where('tenant_id',$c->tenant_id)->where('status','ACTIVE')->pluck('role_code')->all();if(!array_intersect($roles,['SYSTEM_ADMIN','PLATFORM_ADMIN','CLAIMS_MANAGER','CLAIMS_OFFICER']))throw ValidationException::withMessages(['authority'=>__('wave7.authority_exceeded')]);if($c->carrier_reference)return['mode'=>'CARRIER_DIRECT','carrier_reference'=>$c->carrier_reference,'checked_at'=>now()->toIso8601String()];$max=DB::table('delegated_authority_agreements as d')->join('partners as p','p.id','=','d.partner_id')->where('p.tenant_id',$c->tenant_id)->where('d.carrier_id',$c->policy->carrier_id)->where('d.status','ACTIVE')->whereDate('d.effective_from','<=',now())->whereDate('d.effective_until','>=',now())->max('d.max_claim_authority_minor');if($max===null||$amount>(int)$max)throw ValidationException::withMessages(['authority'=>__('wave7.authority_exceeded')]);return['mode'=>'DELEGATED','maximum_minor'=>(int)$max,'checked_at'=>now()->toIso8601String()];}
private function tenant(Claim$c):void{if($c->tenant_id!==app(\App\Domain\Tenancy\TenantContext::class)->id())abort(404);}
private function event(Claim$c,?string$from,string$to,string$type,string$reason,?User$actor,array$details):void{DB::table('claim_events')->insert(['id'=>(string)Str::uuid(),'claim_id'=>$c->id,'type'=>$type,'from_status'=>$from,'to_status'=>$to,'reason_code'=>$reason,'actor_id'=>$actor?->id,'details'=>json_encode($details,JSON_THROW_ON_ERROR),'occurred_at'=>now()]);}
}
